import logging
from subprocess import Popen, PIPE
import time
import re
import six
from ipaddress import IPv6Address, ip_address


class TimeoutException(Exception):
    pass


class VMWait(object):
    def __init__(self):
        self._log = logging.getLogger(__name__)

    def wait_for_vm_availability(self, ip, timeout=300, n_packets_recv=60):
        """
        Virtual machines are not available immediately after stack creation. This keyword pauses another operations
        until VM is pingable. If n seconds defined by given timeout passes, then TimeoutException is raised.

        :param ip: IP address, example: 127.0.0.1
        :param timeout: timeout in seconds
        :param n_packets_recv: how many packets in row should be received
        :return: return code as int, boolean depend of percentage of received packets (must be 0% packet loss)
        """
        max_timeout = int(timeout)
        min_packets_recv = int(n_packets_recv)
        start = time.time()
        time.clock()
        elapsed = 0
        received_packets = 0
        zper = False
        while elapsed <= max_timeout:
            received_packets, zper = self._ip_can_receive_packets(ip, min_packets_recv)
            self._log.debug("Exit code from _ip_can_receive_packets method is: {}\n100% packets received? :{}"
                            .format(received_packets, zper))
            elapsed = time.time() - start
            if elapsed > min_packets_recv and received_packets == 0 and zper is True:
                self._log.info("VM with ip:{} was reachable during {}s in a row".format(ip, elapsed))
                break
        if elapsed >= max_timeout and received_packets != 0 or zper is False:
            raise TimeoutException("VM wasn't available during {}s timeout".format(max_timeout))

    def _ip_can_receive_packets(self, ip, packet_count):
        ping_prog = 'ping6' if self._is_ip_v6(ip) else 'ping'
        ping = Popen(["{}".format(ping_prog),
                      "-c",
                      "{}".format(packet_count),
                      "{}".format(ip)],
                     stdout=PIPE,
                     stderr=PIPE)
        stdout, stderr = ping.communicate()
        zper = self._check_stdout(stdout)
        self._log.debug(stdout)
        return ping.returncode, zper

    def _check_stdout(self, stdout):
        expected_result = "0% packet loss"
        pattern = r"\d*% packet loss"
        decoded_stdout = stdout.decode('utf-8', "ignore")
        result = re.search(pattern=pattern, string=decoded_stdout)
        if result is None:
            return False
        packet_result = result.group()
        self._log.debug("Found pattern: {}".format(packet_result))
        return packet_result == expected_result

    def _is_ip_v6(self, ip):
        return isinstance(ip_address(six.u(ip)), IPv6Address)
